import pytest
import click


def test_func_param_type_value_error_message(runner):
    class MyClass:
        def __init__(self, value):
            self.value = value

        @staticmethod
        def from_str(input_value):
            if input_value != "works":
                raise ValueError(f"input was {input_value!r}, should be 'works'")
            return MyClass(input_value)

    @click.command()
    @click.argument("mydata", type=click.types.FuncParamType(MyClass.from_str))
    def cli(mydata):
        click.echo(f"Success: {mydata.value}")

    result = runner.invoke(cli, ["fails"])
    assert result.exit_code == 2
    assert "Error: Invalid value: input was 'fails', should be 'works'" in result.output
